import {readFileSync, writeFileSync} from 'node:fs';
import vm from 'node:vm';
import {performance} from 'node:perf_hooks';
const source=readFileSync(process.argv[2], 'utf8');
const ctx=vm.createContext({nativePrevious:()=>JSON.stringify({value:'',error:''}),nativePreserveCorrupt:()=>'',nativeWrite:()=>''});
vm.runInContext(source,ctx);
const core=ctx.XunjuCore;
core.initialize('',0,30);
const created=JSON.parse(core.dispatch(JSON.stringify({operation:'add',value:'性能样本'})));
const state=created.state, h=state.houses[0];
state.houses=Array.from({length:30},(_,i)=>({...structuredClone(h),id:'perf-'+i}));
core.initialize(JSON.stringify(state),0,30);
const ops=[{operation:'form',id:'perf-0',view:{phase:'全部',query:'',filters:[]},folds:{}},{operation:'inspectionGuide',id:'perf-0'},{operation:'media',id:'perf-0'}];
const samples=[];let bytes=0;
for(let i=0;i<12;i++) {
 let size=0;const start=performance.now();
 for(const op of ops){const json=core.dispatch(JSON.stringify(op),true);const v=JSON.parse(json);if(!v.ok)throw Error(v.error);size+=Buffer.byteLength(json);}
 const elapsed=performance.now()-start;
 if(i>1)samples.push(elapsed);bytes=size;
}
const result={runtime:process.version,houses:30,operations:ops.map(x=>x.operation),bytesPerCycle:bytes,medianMs:samples.toSorted((a,b)=>a-b)[5],samplesMs:samples};
console.log(JSON.stringify(result,null,2));
if(process.argv[3])writeFileSync(process.argv[3],JSON.stringify(result,null,2));

